// 音声パス: LangChain Gemini の transcribeRecording 出力
// テキストパス: Telegram メッセージ（message フィールドあり）

const input = $input.first().json;
let memoText = '';
let sourceType = 'text';
let chatId = '';
let username = 'unknown';
let telegramMsgId = '';
let telegramUserId = '';

if (input.message) {
  // ── テキストパス: Telegram メッセージがそのまま流れてくる ──
  const msg  = input.message || {};
  memoText   = msg.text || '';
  sourceType = 'text';
  chatId     = String(msg.chat?.id || '');
  username   = msg.from?.username || msg.from?.first_name || 'unknown';
  telegramMsgId  = String(msg.message_id || '');
  telegramUserId = String(msg.from?.id   || '');
} else {
  // ── 音声パス: LangChain Gemini 出力 ──
  memoText   = input?.content?.parts?.[0]?.text || input?.text || '(文字起こし失敗)';
  sourceType = 'voice';
  // chatId / username は Telegram受信から取得
  try {
    const trigMsg = $('📨 Telegram受信').first().json.message || {};
    chatId     = String(trigMsg.chat?.id || '');
    username   = trigMsg.from?.username || trigMsg.from?.first_name || 'unknown';
    telegramMsgId  = String(trigMsg.message_id || '');
    telegramUserId = String(trigMsg.from?.id   || '');
  } catch(e) {}
}

// username: GAS バリデーション回避（/ \ . : をアンダースコアに置換）
username = username.replace(/[\/\\.:]/g, '_').replace(/_+/g, '_').replace(/^_|_$/g, '').substring(0, 50) || 'unknown';

// ── Layer 1 正規化 ──
memoText = memoText.replace(/ゾップ|ゾッポ|ExOP|X\.O\.P/gi, 'XOP');
memoText = memoText.replace(/プロテア(?!ケア)|プロテカ|プロテーケア|プロテラ/g, 'プロテケア');
memoText = memoText.replace(/ウォーターセラミックス|水セラミック/g, 'ウォーターセラミック');
memoText = memoText.replace(/クラック(?!ス)|クラクス/g, 'クラックス');
memoText = memoText.replace(/湯沢/g, '湯澤');
memoText = memoText.replace(/稲沢/g, '稲澤');
memoText = memoText.replace(/中沢/g, '中澤');
memoText = memoText.replace(/笹木/g, '佐々木');
memoText = memoText.replace(/パナホーム(?!リフォーム)/g, 'Panaホームリフォーム');
memoText = memoText.replace(/アルティス/g, 'Artis');
memoText = memoText.replace(/マリナベイシップ/g, 'MarinaBayShip株式会社');
memoText = memoText.replace(/アナザーストーリージャパン/g, 'AnotherStoryJapan');
memoText = memoText.replace(/起訴者/g, 'キーストーン社');

// 音声の場合：日本語間の余分なスペース除去
if (sourceType === 'voice') {
  for (let i = 0; i < 3; i++) {
    memoText = memoText.replace(
      /([ぁ-んァ-ヶー一-龯、。！？])[\s\u3000]+([ぁ-んァ-ヶー一-龯、。！？])/g,
      '$1$2'
    );
  }
}

// ── JST タイムスタンプ ──
const now = new Date();
const jst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
const yyyy = jst.getUTCFullYear();
const mm   = String(jst.getUTCMonth() + 1).padStart(2, '0');
const dd   = String(jst.getUTCDate()).padStart(2, '0');
const hh   = String(jst.getUTCHours()).padStart(2, '0');
const min  = String(jst.getUTCMinutes()).padStart(2, '0');
const dateStr = `${yyyy}-${mm}-${dd}`;

// ── YAML フロントマター + 本文 ──
const markdown = `---
member: ${username}
date: ${dateStr}
time: ${hh}:${min}
source: ${sourceType}
telegram_chat_id: ${chatId}
telegram_message_id: ${telegramMsgId}
telegram_user_id: ${telegramUserId}
created_at: ${now.toISOString()}
---

${memoText}
`;

return {
  chatId, username, content: markdown,
  memoText, sourceType, dateStr,
  timeStr: `${hh}${min}`
};

// 保存結果を確認して返信テキストを生成
const gasResult = $input.first().json;
const meta      = $('📝 メモ整形 (YAML+正規化)').first().json;

const icon = meta.sourceType === 'voice' ? '🎤' : '📝';

let replyText;
if (gasResult.success) {
  const preview = meta.memoText.length > 500
    ? meta.memoText.substring(0, 500) + '\n...(以下省略)'
    : meta.memoText;
  replyText =
    `${icon} *INBOXに保存しました* (${meta.timeStr.slice(0,2)}:${meta.timeStr.slice(2)})\n` +
    `📄 \`${gasResult.path}\`\n\n` +
    `${preview}\n\n` +
    `─────────────\n` +
    `修正は「修正: 内容」、削除は「削除」と返信してください。`;
} else {
  replyText =
    `⚠️ *Drive保存に失敗しました*\n` +
    `エラー: ${gasResult.error}\n\n` +
    `${icon} 文字起こし結果:\n${meta.memoText}`;
}

return {
  chatId : meta.chatId,
  text   : replyText
};
